p("Caesar cipher", "M", "strings", "caesar", "s, shift", "Shift each letter forward by `shift` positions in the alphabet (wrapping around, preserving case). Non-letters stay unchanged. `shift` may be negative.", ["Use `ord` and modulo 26."],
  "def caesar(s, shift):\n    out = []\n    for c in s:\n        if 'a' <= c <= 'z':\n            out.append(chr((ord(c) - 97 + shift) % 26 + 97))\n        elif 'A' <= c <= 'Z':\n            out.append(chr((ord(c) - 65 + shift) % 26 + 65))\n        else:\n            out.append(c)\n    return ''.join(out)", "Modulo handles wrap-around in both directions.", [("abc", 1), ("xyz", 3)], [("Hello, World!", 5), ("abc", -1), ("abc", 26), ("Zz", 13)])
