p("Palindrome ignoring punctuation", "M", "strings", "is_palindrome_phrase", "s", "Return `True` if `s` is a palindrome considering only letters and digits and ignoring case. (An empty cleaned string is a palindrome.)", ["Clean first, then compare with the reverse."],
  "def is_palindrome_phrase(s):\n    t = [c.lower() for c in s if c.isalnum()]\n    return t == t[::-1]", "Filter with `isalnum`.", [("A man, a plan, a canal: Panama",), ("race a car",)], [("",), (".,",), ("No lemon, no melon",), ("ab",)])
p("Longest palindromic substring length", "H", "strings", "longest_palindrome_len", "s", "Return the length of the longest palindromic substring of `s` (`s` non-empty).", ["Expand around each centre (odd and even)."],
  "def longest_palindrome_len(s):\n    best = 1\n    for c in range(len(s)):\n        for l, r in ((c, c), (c, c + 1)):\n            while l >= 0 and r < len(s) and s[l] == s[r]:\n                best = max(best, r - l + 1)\n                l -= 1\n                r += 1\n    return best", "Expanding around 2n-1 centres is O(n²).", [("babad",), ("cbbd",)], [("a",), ("abcd",), ("forgeeksskeegfor",), ("aaaa",)], lambda r: ("".join(r.choice("ab") for _ in range(r.randint(5, 20))),))
p("Count palindromic substrings", "H", "strings", "count_palindromic_substrings", "s", "Count substrings of `s` (by position, so repeats count separately) that are palindromes.", ["Expand around each centre and count every success."],
  "def count_palindromic_substrings(s):\n    total = 0\n    for c in range(len(s)):\n        for l, r in ((c, c), (c, c + 1)):\n            while l >= 0 and r < len(s) and s[l] == s[r]:\n                total += 1\n                l -= 1\n                r += 1\n    return total", "Each successful expansion is one palindrome.", [("abc",), ("aaa",)], [("",), ("a",), ("abba",), ("racecar",)], lambda r: ("".join(r.choice("ab") for _ in range(r.randint(3, 12))),))
p("Isomorphic strings", "M", "dicts", "is_isomorphic", "a, b", "Two strings are isomorphic if characters in `a` can be replaced to get `b` with a one-to-one mapping preserving order. Return whether `a` and `b` are isomorphic.", ["Track both directions of the mapping."],
  "def is_isomorphic(a, b):\n    if len(a) != len(b):\n        return False\n    ab, ba = {}, {}\n    for x, y in zip(a, b):\n        if ab.setdefault(x, y) != y or ba.setdefault(y, x) != x:\n            return False\n    return True", "Both maps must be consistent.", [("egg", "add"), ("foo", "bar")], [("paper", "title"), ("ab", "aa"), ("", ""), ("a", "aa")])
p("Word pattern", "M", "dicts", "word_pattern", "pattern, text", "Given a pattern like `\"abba\"` and a space-separated `text`, return whether the words follow the same pattern (bijection between letters and words).", ["Same idea as isomorphic strings, on words."],
  "def word_pattern(pattern, text):\n    words = text.split()\n    if len(words) != len(pattern):\n        return False\n    pw, wp = {}, {}\n    for c, w in zip(pattern, words):\n        if pw.setdefault(c, w) != w or wp.setdefault(w, c) != c:\n            return False\n    return True", "A bijection needs checks in both directions.", [("abba", "dog cat cat dog"), ("abba", "dog cat cat fish")], [("aaaa", "dog cat cat dog"), ("abc", "b c a"), ("ab", "x x")])
p("Remove adjacent duplicates repeatedly", "M", "stacks", "remove_adjacent_pairs", "s", "Repeatedly delete pairs of equal adjacent characters until none remain; return the final string.", ["A stack handles cascading removals."],
  "def remove_adjacent_pairs(s):\n    stack = []\n    for c in s:\n        if stack and stack[-1] == c:\n            stack.pop()\n        else:\n            stack.append(c)\n    return ''.join(stack)", "Each character either cancels the top or is pushed.", [("abbaca",), ("azxxzy",)], [("",), ("aa",), ("abc",), ("aabbaa",)])
p("String to integer", "M", "parsing", "my_atoi", "s", "Parse a string to an integer like `int`: ignore leading spaces, accept an optional `+`/`-`, read leading digits and stop at the first non-digit. Return 0 if no digits. Clamp to the 32-bit signed range `[-2**31, 2**31 - 1]`.", ["Handle sign, digits, then clamp."],
  "def my_atoi(s):\n    i, n = 0, len(s)\n    while i < n and s[i] == ' ':\n        i += 1\n    sign = 1\n    if i < n and s[i] in '+-':\n        sign = -1 if s[i] == '-' else 1\n        i += 1\n    val = 0\n    while i < n and s[i].isdigit():\n        val = val * 10 + int(s[i])\n        i += 1\n    val *= sign\n    return max(-2**31, min(2**31 - 1, val))", "Parse in stages, clamp at the end.", [("42",), ("   -42",)], [("4193 with words",), ("words 987",), ("",), ("-91283472332",), ("+1",)])
p("Roman to integer", "M", "parsing", "roman_to_int", "s", "Convert a valid Roman numeral (up to 3999) to an integer.", ["If a symbol is smaller than the next one, subtract it."],
  "def roman_to_int(s):\n    v = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}\n    total = 0\n    for i, c in enumerate(s):\n        if i + 1 < len(s) and v[c] < v[s[i + 1]]:\n            total -= v[c]\n        else:\n            total += v[c]\n    return total", "Subtractive notation means a smaller value before a bigger one.", [("III",), ("MCMXCIV",)], [("IV",), ("LVIII",), ("MMMCMXCIX",), ("IX",)])
p("Integer to Roman", "M", "parsing", "int_to_roman", "n", "Convert an integer from 1 to 3999 to a Roman numeral.", ["Greedily subtract the largest values, including 900, 400, 90, 40, 9, 4."],
  "def int_to_roman(n):\n    table = [(1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'), (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'), (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I')]\n    out = []\n    for value, sym in table:\n        while n >= value:\n            out.append(sym)\n            n -= value\n    return ''.join(out)", "Include subtractive pairs in the table and the greedy approach works.", [(3,), (1994,)], [(4,), (9,), (58,), (3999,), (444,)])
p("Excel column title", "M", "parsing", "column_title", "n", "Convert a column number to its Excel title: 1 -> `\"A\"`, 26 -> `\"Z\"`, 27 -> `\"AA\"`, 701 -> `\"ZY\"`.", ["It is bijective base-26: subtract 1 each step."],
  "def column_title(n):\n    out = []\n    while n > 0:\n        n -= 1\n        out.append(chr(65 + n % 26))\n        n //= 26\n    return ''.join(reversed(out))", "Subtracting one first turns 1..26 into 0..25.", [(1,), (28,)], [(26,), (27,), (52,), (701,), (703,)])
p("Binary string addition", "M", "strings", "add_binary", "a, b", "Add two binary numbers given as strings (no leading zeros except `\"0\"`) and return the sum as a binary string.", ["Add from the right with a carry."],
  "def add_binary(a, b):\n    i, j, carry = len(a) - 1, len(b) - 1, 0\n    out = []\n    while i >= 0 or j >= 0 or carry:\n        total = carry\n        if i >= 0:\n            total += int(a[i]); i -= 1\n        if j >= 0:\n            total += int(b[j]); j -= 1\n        out.append(str(total % 2))\n        carry = total // 2\n    return ''.join(reversed(out))", "Grade-school addition in base 2.", [("11", "1"), ("1010", "1011")], [("0", "0"), ("1", "1"), ("111", "111"), ("100", "0")])
p("Strip comments", "M", "parsing", "strip_comments", "lines", "Given a list of source lines, remove everything from the first `#` to the end of each line, strip trailing whitespace, and drop lines that become empty. Return the cleaned lines.", ["`line.split('#')[0].rstrip()`."],
  "def strip_comments(lines):\n    out = []\n    for line in lines:\n        code = line.split('#')[0].rstrip()\n        if code:\n            out.append(code)\n    return out", "Comments run to the end of the line.", [(["x = 1  # one", "# note", "y = 2"],), (["a", "b"],)], [([],), (["   # only comment"],), (["z = 3 # c # d"],)])
p("Wrap text", "M", "strings", "wrap_text", "text, width", "Split `text` into lines of at most `width` characters, breaking only at spaces (words longer than `width` stay alone on their line). Return the list of lines; words are separated by single spaces.", ["Greedily add words while the line fits."],
  "def wrap_text(text, width):\n    lines, cur = [], ''\n    for w in text.split():\n        if not cur:\n            cur = w\n        elif len(cur) + 1 + len(w) <= width:\n            cur += ' ' + w\n        else:\n            lines.append(cur)\n            cur = w\n    if cur:\n        lines.append(cur)\n    return lines", "Greedy filling gives the standard result.", [("the quick brown fox", 10), ("a b c", 3)], [("", 5), ("supercalifragilistic is long", 8), ("one two three", 100)])
p("Text justify center", "E", "strings", "center_text", "s, width", "Center `s` in a field of `width` characters using spaces. If padding is odd put the extra space on the right. If `s` is at least `width` long return it unchanged.", ["Left pad is `(width - len) // 2`."],
  "def center_text(s, width):\n    pad = width - len(s)\n    if pad <= 0:\n        return s\n    left = pad // 2\n    return ' ' * left + s + ' ' * (pad - left)", "Integer division puts the extra space on the right.", [("hi", 6), ("odd", 6)], [("long", 2), ("", 3), ("a", 2)])
p("Mask a card number", "E", "strings", "mask_card", "number", "Replace all but the last four characters with `*`. Strings of 4 or fewer characters are returned unchanged.", ["`'*' * (len - 4) + s[-4:]`."],
  "def mask_card(number):\n    if len(number) <= 4:\n        return number\n    return '*' * (len(number) - 4) + number[-4:]", "Slicing from the end keeps the last four.", [("1234567890123456",), ("123",)], [("",), ("12345",), ("4444",)])
p("Valid identifier", "M", "strings", "is_valid_identifier", "s", "Return `True` if `s` is a valid simple identifier: non-empty, starts with a letter or underscore, and contains only letters, digits and underscores (ASCII).", ["Check the first character separately."],
  "def is_valid_identifier(s):\n    if not s or not (s[0].isalpha() or s[0] == '_') or not s[0].isascii():\n        return False\n    return all(c.isascii() and (c.isalnum() or c == '_') for c in s)", "First char differs from the rest.", [("var_1",), ("1var",)], [("",), ("_",), ("a-b",), ("x y",), ("Name2",)])
