p("Run lengths as pairs", "M", "strings", "run_pairs", "s", "Return the runs of identical consecutive characters as a list of `[char, count]` pairs.", ["Walk the string, extending the last run when the character repeats."],
  "def run_pairs(s):\n    out = []\n    for c in s:\n        if out and out[-1][0] == c:\n            out[-1][1] += 1\n        else:\n            out.append([c, 1])\n    return out", "Mutate the last pair in place.", [("aaabcc",), ("z",)], [("",), ("abc",), ("aabbaa",)])
