p("Longest substring without repeats", "H", "sliding-window", "longest_unique_substring", "s", "Return the length of the longest substring of `s` without repeated characters.", ["Sliding window with last-seen indices."],
  "def longest_unique_substring(s):\n    last, start, best = {}, 0, 0\n    for i, c in enumerate(s):\n        if c in last and last[c] >= start:\n            start = last[c] + 1\n        last[c] = i\n        best = max(best, i - start + 1)\n    return best", "Move the window start just past the previous occurrence.", [("abcabcbb",), ("bbbbb",)], [("",), ("pwwkew",), ("abcdef",), ("dvdf",)], lambda r: ("".join(r.choice("abcd") for _ in range(r.randint(3, 15))),))
p("Minimum window substring length", "H", "sliding-window", "min_window_len", "s, t", "Return the length of the smallest substring of `s` containing every character of `t` (with multiplicity), or `0` if none exists. `t` is non-empty.", ["Expand right to satisfy, then shrink left."],
  "def min_window_len(s, t):\n    from collections import Counter\n    need = Counter(t)\n    missing = len(t)\n    best = 0\n    left = 0\n    for right, c in enumerate(s):\n        if need[c] > 0:\n            missing -= 1\n        need[c] -= 1\n        if missing == 0:\n            while need[s[left]] < 0:\n                need[s[left]] += 1\n                left += 1\n            size = right - left + 1\n            if best == 0 or size < best:\n                best = size\n            need[s[left]] += 1\n            missing += 1\n            left += 1\n    return best", "The classic two-pointer window with a deficit counter.", [("ADOBECODEBANC", "ABC"), ("a", "aa")], [("a", "a"), ("aa", "aa"), ("abc", "d"), ("bba", "ab")])
